        "SmsAllowed" boolean NOT NULL,
        "TaxExempt" boolean NOT NULL,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100) NOT NULL,
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        CONSTRAINT "PK_CrmDefaultServiceLocation" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_CrmDefaultServiceLocation_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES crm."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
